<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Core.php';use Wams\Core;
session_name('WAMSSESSID');session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax','cookie_secure'=>isset($_SERVER['HTTPS'])]);$c=new Core();$p=(string)($_GET['p']??'home');$error='';
function h(mixed $x):string{return htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function go(string $p):never{header('Location:?p='.rawurlencode($p));exit;}
try{if(!$c->installed()){http_response_code(503);throw new RuntimeException('Installation ist nicht abgeschlossen.');}if($p==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){if($c->login(trim((string)$_POST['login']),(string)$_POST['password']))go('home');$error='Anmeldung fehlgeschlagen.';}if($p==='logout'){session_destroy();go('login');}if($p!=='login')$u=$c->requireUser();
if($p==='asset'&&isset($u)){$i=$c->instance((string)($_GET['id']??''));if(!$c->allowed($u,$i,$i['app_id'].'.view')){http_response_code(403);exit;}$rel=(string)($_GET['file']??'');$base=realpath(dirname(__DIR__).'/applications/'.$i['app_id']);$file=realpath($base.'/'.$rel);if(!$base||!$file||!str_starts_with($file,$base.'/')){http_response_code(404);exit;}$ext=pathinfo($file,PATHINFO_EXTENSION);header('Content-Type: '.($ext==='css'?'text/css':'application/javascript'));readfile($file);exit;}
if($p==='run'&&isset($u)){$i=$c->instance((string)($_GET['id']??''));if(!$c->allowed($u,$i,$i['app_id'].'.view')){http_response_code(403);exit('Nicht erlaubt.');}$wams=['authorized'=>true,'config'=>$c->config($i['id']),'canManage'=>$c->allowed($u,$i,$i['app_id'].'.manage'),'manageUrl'=>'?p=manage&id='.rawurlencode($i['id']),'styleUrl'=>'?p=asset&id='.rawurlencode($i['id']).'&file='.rawurlencode('styles/default/1.0.0/style.css'),'scriptUrl'=>'?p=asset&id='.rawurlencode($i['id']).'&file='.rawurlencode('public/assets/app.js')];echo '<link rel="stylesheet" href="assets/style.css"><a class="back" href="?p=home">←</a>';require dirname(__DIR__).'/applications/'.$i['app_id'].'/public/index.php';exit;}
if(isset($u)&&$_SERVER['REQUEST_METHOD']==='POST'){$c->check();if($p==='tenant-new'&&$u['is_global']){$q=$c->db->prepare('INSERT INTO tenants VALUES(?,?,?)');$q->execute([$c->id(),trim((string)$_POST['name']),gmdate('c')]);go('tenants');}if($p==='app-install'){$cfg=json_decode((string)$_POST['config'],true);if(!is_array($cfg))throw new RuntimeException('Konfiguration ist kein JSON-Objekt.');$c->install((string)$_POST['tenant'],(string)$_POST['app'],trim((string)$_POST['name']),$cfg,$u,(string)$_POST['access']);go('apps');}if($p==='save'){$i=$c->instance((string)$_POST['id']);if(!$c->allowed($u,$i,$i['app_id'].'.manage'))throw new RuntimeException('Kein Verwaltungsrecht.');$cfg=json_decode((string)$_POST['config'],true);if(!is_array($cfg))throw new RuntimeException('Ungültiges JSON.');$c->save($i['id'],$cfg);header('Location:?p=manage&id='.rawurlencode($i['id']));exit;}}
}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WAMS</title><link rel="stylesheet" href="assets/style.css"></head><body><header><b>WAMS</b><?php if(isset($u)):?><nav><a href="?p=home">Launcher</a><a href="?p=apps">Apps</a><a href="?p=tenants">Tenants</a><a href="?p=logout">Abmelden</a></nav><?php endif?></header><main class="wrap"><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
