<?php elseif($p==='home'):$ts=$c->tenants($u);?><h1>App Launcher</h1><div class="grid"><?php foreach($ts as $t):$q=$c->db->prepare('SELECT * FROM app_instances WHERE tenant_id=?');$q->execute([$t['id']]);foreach($q as $i):if(!$c->allowed($u,$i,$i['app_id'].'.view'))continue;?><section class="card"><span class="muted"><?=h($t['name'])?></span><h2><?=h($i['name'])?></h2><a class="btn" href="?p=run&amp;id=<?=h($i['id'])?>">Öffnen</a><?php if($c->allowed($u,$i,$i['app_id'].'.manage')):?><a href="?p=manage&amp;id=<?=h($i['id'])?>">Verwalten</a><?php endif?></section><?php endforeach;endforeach?></div>
<?php elseif($p==='tenants'):$ts=$c->tenants($u);?><h1>Tenants</h1><?php if($u['is_global']):?><section class="card"><form method="post" action="?p=tenant-new"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Name</label><input name="name" required><button>Anlegen</button></form></section><?php endif?><section class="card"><?php foreach($ts as $t):?><p><?=h($t['name'])?> <code><?=h($t['id'])?></code></p><?php endforeach?></section>
<?php elseif($p==='apps'):$ts=$c->tenants($u);$apps=$c->catalog();?><h1>App installieren</h1><section class="card"><form method="post" action="?p=app-install"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Tenant</label><select name="tenant"><?php foreach($ts as $t):?><option value="<?=h($t['id'])?>"><?=h($t['name'])?></option><?php endforeach?></select><label>App</label><select name="app"><?php foreach($apps as $a):?><option value="<?=h($a['appId'])?>"><?=h($a['name'])?></option><?php endforeach?></select><label>Instanzname</label><input name="name" required><label>Konfiguration</label><textarea name="config" rows="14">{"remoteUrl":"https://example.org/report.csv","title":"CSV Reporting","heading":"CSV Reporting","delimiter":",","refreshSeconds":0,"timeoutSeconds":20,"hasHeader":true}</textarea><label>Zugriff</label><select name="access"><option value="tenant">gesamter Tenant</option><option value="user">nur ich</option><option value="none">niemand</option></select><button>Prüfen und installieren</button></form></section>
<?php elseif($p==='manage'):$i=$c->instance((string)($_GET['id']??''));if(!$c->allowed($u,$i,$i['app_id'].'.manage')):?><div class="error">Kein Verwaltungsrecht.</div><?php else:?><h1><?=h($i['name'])?> verwalten</h1><section class="card"><form method="post" action="?p=save"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="id" value="<?=h($i['id'])?>"><textarea name="config" rows="18"><?=h(json_encode($c->config($i['id']),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></textarea><button>Remote-Quelle prüfen und speichern</button></form></section><?php endif?>
<?php endif?></main></body></html>
